#!/usr/bin/env python3

# Human P53 protein amino acid sequence
target_aa = ""

# DNA sequences from the plasmids
sequences = {
    'A': '',
    'B': '',
    'C': '',
    'D': ''
}

def translate_dna(dna_seq):
    """Translate DNA sequence to amino acids"""
    codon_table = {
        'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
        'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
        'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
        'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
        'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
        'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
        'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
        'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
        'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
        'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
        'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
        'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
        'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
        'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
        'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
        'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G'
    }
    
    protein = ""
    for i in range(0, len(dna_seq), 3):
        codon = dna_seq[i:i+3]
        if len(codon) == 3:
            protein += codon_table.get(codon, 'X')
    return protein

def analyze_sequence(name, dna_seq):
    """Analyze a DNA sequence and compare to target"""
    protein = translate_dna(dna_seq)
    
    print(f"\n=== PLASMID {name} ===")
    print(f"Length: {len(dna_seq)} bp")
    print(f"Protein length: {len(protein)} aa")
    
    # Compare to target
    matches = sum(1 for a, b in zip(protein, target_aa) if a == b)
    identity = (matches / len(target_aa)) * 100
    
    print(f"Identity to target: {matches}/{len(target_aa)} ({identity:.1f}%)")
    
    # Remove stop codon if present
    if protein.endswith('*'):
        protein = protein[:-1]
    
    if protein == target_aa:
        print("✓ CORRECT - Matches target sequence exactly")
        is_correct = True
    else:
        print("✗ INCORRECT - Differences found:")
        is_correct = False
        for i, (target, actual) in enumerate(zip(target_aa, protein)):
            if target != actual:
                print(f"  Position {i+1}: Expected {target}, Got {actual}")
                # Show surrounding context
                start = max(0, i-5)
                end = min(len(target_aa), i+6)
                print(f"    Target:  ...{target_aa[start:end]}...")
                print(f"    Actual:  ...{protein[start:end]}...")
        # Check if it's just a length difference
        if len(protein) != len(target_aa):
            print(f"  Length difference: Target={len(target_aa)}, Actual={len(protein)}")
    
    return is_correct, protein

# Analyze all sequences
correct_plasmids = []
for name, seq in sequences.items():
    is_correct, protein = analyze_sequence(name, seq)
    if is_correct:
        correct_plasmids.append((name, seq))

print(f"\n=== SUMMARY ===")
print(f"Correct plasmids: {[name for name, _ in correct_plasmids]}")

if correct_plasmids:
    print("\n=== CODON OPTIMIZATION ANALYSIS ===")
    # E. coli codon usage preferences (simplified)
    rare_codons = ['AGA', 'AGG', 'CGA', 'CCC', 'CGG', 'CTA', 'ATA']
    
    for name, seq in correct_plasmids:
        print(f"\nPlasmid {name}:")
        rare_count = 0
        for i in range(0, len(seq), 3):
            codon = seq[i:i+3]
            if codon in rare_codons:
                rare_count += 1
        print(f"  Rare codons: {rare_count}")
        
        # Count specific problematic codons
        ccc_count = seq.count('CCC')  # Rare proline codon
        aga_count = seq.count('AGA')  # Rare arginine codon
        cga_count = seq.count('CGA')  # Rare arginine codon
        
        print(f"  CCC (rare Pro): {ccc_count}")
        print(f"  AGA (rare Arg): {aga_count}")
        print(f"  CGA (rare Arg): {cga_count}")